import{_ as a,o as e,c as n,ag as d}from"./chunks/framework.C9sp7nFj.js";const _=JSON.parse('{"title":"GetSyncSignal 获取同步信号","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/21. 主从运动指令/GetSyncSignal.md","filePath":"3. 指令/21. 主从运动指令/GetSyncSignal.md","lastUpdated":1778862643000}'),r={name:"3. 指令/21. 主从运动指令/GetSyncSignal.md"};function i(l,t,c,o,h,s){return e(),n("div",null,[...t[0]||(t[0]=[d('<h1 id="getsyncsignal-获取同步信号" tabindex="-1">GetSyncSignal 获取同步信号 <a class="header-anchor" href="#getsyncsignal-获取同步信号" aria-label="Permalink to &quot;GetSyncSignal 获取同步信号&quot;">​</a></h1><p>该指令用于使从机器人获取到主机器人已执行到指定行的索引信息，便于该从机器人根据该索引信息做出对应的功能操作。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>GetSyncSignal(SyncId, SignalId) GetSyncSignal(协同标识, 信号索引)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>SyncId</td><td>SYNCID 变量</td><td>机器人协同标识 ID 号，用于本机与协同机器人之间进行协同校验，主从机器人 ID 一致时才为有效协同。</td><td></td></tr><tr><td>SignalId</td><td>INT 变量</td><td>机器人信号索引值，当从机器人执行到该指令时，根据协同标识来获取主机器人所发出的信号索引值，并赋值给该变量。</td><td></td></tr></tbody></table>',7)])])}const g=a(r,[["render",i]]);export{_ as __pageData,g as default};
